 function renderVisual(){if(!task||!session)return;const oldObjects=new Map([...$('mission-visual').querySelectorAll('[data-object]')].map(el=>[el.dataset.object,el.cloneNode(true)])),oldAngles=new Map([...$('mission-visual').querySelectorAll('[data-clock-hand]')].map(el=>[el.dataset.clockHand,num(el.dataset.angle)]));const raw=answerValue(),proposal={};if(raw&&typeof raw==='object'){for(const [k,val]of Object.entries(raw)){const n=A.parseAnswer(val);if(n!==null)proposal[k]=n;}}else{const n=A.parseAnswer(raw);if(n!==null)proposal.value=n;}const drawing=renderer(getVisual(),proposed(),proposal);if(Object.keys(proposal).length&&!young()){drawing.markup=drawing.markup.replace('</svg>',`<g data-proposal="${esc(JSON.stringify(proposal))}"><text x="280" y="335" text-anchor="middle" font-size="10" fill="#8a603e">Your trial: ${esc(Object.entries(proposal).map(([k,v])=>k+' = '+fmt(v)).join(' · '))}</text></g></svg>`);}$('mission-visual').innerHTML=drawing.markup;animateModel(oldObjects,oldAngles);$('mission-readout').textContent=drawing.readout;$('mission-visual-caption').textContent=drawing.caption;}
 function animateModel(oldObjects,oldAngles){
  if(isCalm()||state.preferences.calm||document.body.classList.contains('reduce-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const host=$('mission-visual'),canAnimate=typeof Element.prototype.animate==='function';if(!canAnimate)return;
  const newKeys=new Set();for(const el of host.querySelectorAll('[data-object]')){const key=el.dataset.object;newKeys.add(key);if(!oldObjects.has(key))el.animate([{opacity:0,transform:'translateY(-15px)'},{opacity:1,transform:'translateY(0px)'}],{duration:270,easing:'cubic-bezier(.2,.7,.3,1)'});}
  const surface=host.querySelector('svg');for(const [key,old]of oldObjects){if(!newKeys.has(key)&&surface){old.setAttribute('aria-hidden','true');old.removeAttribute('data-object');surface.append(old);const effect=old.animate([{opacity:.7,transform:'translateY(0px)'},{opacity:0,transform:'translateY(22px)'}],{duration:220,easing:'ease-in',fill:'forwards'});effect.onfinish=()=>old.remove();}}
  for(const hand of host.querySelectorAll('[data-clock-hand]')){const before=oldAngles.get(hand.dataset.clockHand),after=num(hand.dataset.angle);if(before===undefined||before===after)continue;hand.style.transformOrigin='280px 164px';hand.style.transformBox='view-box';const effect=hand.animate([{transform:`rotate(${before}rad)`},{transform:`rotate(${after}rad)`}],{duration:350,easing:'cubic-bezier(.2,.7,.3,1)'});effect.onfinish=()=>{hand.style.transformOrigin='';hand.style.transformBox='';};}
 }
 function chosenBand(){return (A.ageBands||[]).find(b=>b.id===currentBand);}
 function worldOf(mission){return (A.worlds||[]).find(w=>w.id===mission.worldId)||{id:mission.worldId,title:mission.worldId};}
 function bandMissions(){return A.missions.filter(m=>!m.bandId||m.bandId===currentBand);}
 function missionTitle(m){return m.title||m.name||m.id;}
 function missionSkill(m){return m.skill||m.subtitle||m.description||'Explore a new mathematical idea';}
 function worldTitle(w){return w.title||w.name||w.id;}
 function goalCount(){const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate());start.setDate(start.getDate()-((start.getDay()+6)%7));return Object.values(state.completed).filter(c=>new Date(c.completedAt)>=start).length;}
 function applyPreferences(){document.body.dataset.band=currentBand;document.body.classList.toggle('adventure-calm',Boolean(state.preferences.calm));document.body.classList.toggle('adventure-hide-rewards',!state.preferences.rewards);$('adventure-calm').checked=Boolean(state.preferences.calm);$('adventure-rewards').checked=Boolean(state.preferences.rewards);}
