 function updateControl(key,value){const def=(task.inputs||[]).find(i=>i.key===key);if(!def||!Number.isFinite(Number(value)))return;const n=Math.max(num(def.min),Math.min(num(def.max),Math.round((Number(value)-num(def.min))/(num(def.step,1)))*num(def.step,1)+num(def.min)));session.manipulated[session.step][key]=Math.round(n*1e6)/1e6;const range=$('control-'+key),number=$('number-'+key),out=$('control-output-'+key);if(range)range.value=String(n);if(number&&document.activeElement!==number)number.value=String(n);if(out)out.textContent=fmt(n);for(const bump of $('mission-controls').querySelectorAll('[data-control-bump]')){if(bump.dataset.controlBump===key)bump.disabled=num(bump.dataset.delta)<0?n<=num(def.min):n>=num(def.max);}if(accepted){accepted=false;delete session.answers[session.step];$('adventure-next').hidden=true;$('adventure-feedback').textContent='You changed the model. Check your new thinking when you’re ready.';$('adventure-feedback').classList.remove('correct');}renderVisual();saveSession();}
